mapper.select:
SELECT a.id, a.student_id, a.attend_date, a.status, a.remark, s.name as student_name, s.student_no, c.class_name FROM attendance a LEFT JOIN student s ON a.student_id = s.id LEFT JOIN class c ON s.class_id = c.id WHERE s.class_id = #{classId}
AND a.attend_date = #{attendDate}
ORDER BY s.student_no

SELECT s.id as studentId, s.name as studentName, SUM(CASE WHEN a.status = 1 THEN 1 ELSE 0 END) as attendCount, SUM(CASE WHEN a.status = 2 THEN 1 ELSE 0 END) as lateCount, SUM(CASE WHEN a.status = 4 THEN 1 ELSE 0 END) as leaveCount, SUM(CASE WHEN a.status = 5 THEN 1 ELSE 0 END) as absentCount, COUNT(a.id) as totalDays FROM student s LEFT JOIN attendance a ON s.id = a.student_id AND a.attend_date BETWEEN #{startDate} AND #{endDate} WHERE s.deleted = 0
AND s.class_id = #{classId}
GROUP BY s.id, s.name ORDER BY s.student_no
